"""Complete CKD with complications, nutrition and kidney-failure planning."""
from create_ckd import rows,q,CK,AN,MB
from qbank_authoring import finalize

q('What protein-intake principle fits a metabolically stable adult with CKD G3–G5 not on dialysis?', 'Approximately 0.8 g/kg/day, individualized to nutrition and clinical context',[
 ('A high-protein bodybuilding diet for every patient','High intake can be inappropriate in progression risk.'),('Severe restriction without nutritional supervision','This can cause protein-energy wasting.'),('The same restriction must be imposed on every frail or catabolic patient','Nutrition and illness can alter the balance.')],
 'Kidney protection must not create malnutrition', '**KDIGO recommends a moderate protein intake in suitable nondialysis CKD.**', ['Avoid indiscriminate high intake.','Dietitian support helps account for energy and nutritional adequacy.'], '**Distinguish nondialysis care from dialysis or catabolic illness.**', ['Requirements can differ.','Monitor weight, intake and muscle function.'], [['Stable G3–G5','Around 0.8 g/kg/day'],['Frailty/catabolism','Individualize'],['Dialysis','Different nutritional needs']], [CK])
q('Which dietary sodium target is generally suggested in CKD?', 'Less than 2 g sodium daily, roughly 5 g salt, when appropriate',[
 ('Less than 2 g salt is the same amount','Sodium and salt weights are not interchangeable.'),('No sodium review is useful if BP is treated','Intake can influence BP and volume.'),('Universal restriction regardless of sodium-wasting disease','Selected conditions need different advice.')],
 'State the substance and units clearly', '**Lower sodium can support BP and volume control.**', ['Processed foods are important sources.','Potassium-containing salt substitutes can be unsafe in selected patients.'], '**Tailor advice to the physiology.**', ['Review BP, edema and potassium.','Avoid a generic restrictive diet that harms overall nutrition.'], [['Sodium','Below 2 g/day'],['Salt equivalent','About 5 g/day'],['Exceptions','Sodium-wasting or other special contexts']], [CK])
q('A CKD patient asks whether OTC pain medicines matter. What is the best advice?', 'Review NSAIDs and other nonprescribed agents because they can worsen kidney risk, especially during acute illness',[
 ('OTC status guarantees renal safety','It does not.'),('All analgesics have identical kidney effects','Drug class, dose and context differ.'),('Never treat pain in CKD','Pain can be treated using a safer individualized plan.')],
 'Medication reconciliation includes the pharmacy shelf', '**NSAIDs can impair renal autoregulation and create additional toxicity.**', ['Risk can rise with dehydration, RAS blockers and diuretics.','Herbal and supplement exposures also need review.'], '**Provide practical alternatives and a sick-day plan.**', ['Avoid unsupervised substitutions.','Discuss when to seek assessment during vomiting or reduced intake.'], [['OTC','Not automatically safe'],['NSAID','Important kidney-risk exposure'],['Plan','Individualized pain care']], [CK], 'clinical_scenario')
q('A 62-year-old with CKD G3b is not on dialysis and has no contraindication. Which lipid strategy is generally recommended?', 'Statin-based therapy, with statin/ezetimibe an appropriate option in the relevant guideline context',[
 ('No lipid therapy until a myocardial infarction occurs','CKD confers cardiovascular risk.'),('Start a statin only if it will immediately raise eGFR','The principal goal is cardiovascular risk reduction.'),('Use the same rule to automatically initiate statins in every prevalent dialysis patient','The dialysis evidence and recommendations differ.')],
 'Cardiovascular prevention is central to CKD care', '**KDIGO supports statin-based treatment in older adults with nondialysis CKD.**', ['Risk reduction is not limited to lowering a laboratory number.','Drug interactions and dose suitability matter.'], '**Keep the population distinction clear.**', ['Continuation and new initiation at dialysis are separate questions.','Treat other vascular risks too.'], [['Nondialysis older CKD','Statin-based prevention'],['Main target','Cardiovascular events'],['Dialysis','Different initiation guidance']], [CK], 'clinical_scenario')
q('Why should vaccination status be reviewed during advanced CKD planning?', 'Infection risk is increased and vaccine response or scheduling may be more favorable before later immune dysfunction and dialysis',[
 ('CKD protects against severe infection','It does not.'),('All vaccines are permanently contraindicated','Most indicated nonlive vaccines remain important.'),('Only transplantation patients need any vaccine review','Earlier CKD care also provides an opportunity.')],
 'Prevention should precede predictable exposure and immune changes', '**Use current age-, disease- and jurisdiction-specific recommendations.**', ['Hepatitis B preparation can be important before dialysis.','Influenza, pneumococcal and other indicated vaccines need review.'], '**Coordinate future transplant plans.**', ['Live-vaccine timing differs after immune suppression.','Document responses when required by the protocol.'], [['CKD','Higher infection vulnerability'],['Dialysis planning','Hepatitis B review'],['Transplant planning','Timing considerations']], [CK])
q('Hemoglobin falls in CKD. What should occur before attributing anemia entirely to reduced erythropoietin?', 'Assess iron status and other causes such as blood loss, inflammation and nutritional deficiency',[
 ('Give an ESA to every low Hb without evaluation','Correctable causes can be missed.'),('A normal ferritin alone excludes iron-restricted erythropoiesis','Inflammation and TSAT complicate interpretation.'),('CKD excludes gastrointestinal bleeding','The conditions can coexist.')],
 'CKD anemia is often multifactorial', '**KDIGO 2026 begins with CBC, reticulocytes, ferritin and TSAT, extending evaluation as needed.**', ['B12, folate, hemolysis and other tests fit selected patterns.','Unexpected severity or cell abnormalities warrant a broader work-up.'], '**Treat the cause rather than only the number.**', ['Address bleeding and iron deficiency.','Then assess symptom and transfusion risk in treatment planning.'], [['Initial assessment','CBC/reticulocytes/iron'],['Other causes','Bleeding and systemic disease'],['Therapy','Cause- and risk-informed']], [AN])
q('An anemic hemodialysis patient has ferritin 350 ng/mL and TSAT 22%. Which statement fits KDIGO 2026?', 'The values meet the suggested iron-initiation thresholds for anemic CKD G5HD, subject to clinical assessment',[
 ('Ferritin above 100 always prohibits iron in HD','HD-specific thresholds are different.'),('TSAT is irrelevant in dialysis','It helps assess iron availability.'),('Iron should be given without infection or overload review','The clinical context and safety still matter.')],
 'Iron thresholds differ by treatment setting', '**For G5HD, KDIGO suggests initiation when ferritin is at most 500 and TSAT at most 30%.**', ['Use an appropriate IV strategy in the HD context.','Monitor response and avoid excessive exposure.'], '**Do not transplant the rule unchanged to every nondialysis patient.**', ['Inflammation can elevate ferritin.','Review infection and other causes of poor response.'], [['G5HD ferritin','At most 500 ng/mL'],['G5HD TSAT','At most 30%'],['Application','Anemia plus clinical context']], [AN], 'clinical_scenario')
q('An anemic nondialysis CKD patient has ferritin 180 ng/mL and TSAT 18%. Does this fit a KDIGO 2026 suggested iron-initiation profile?', 'Yes; ferritin 100 to below 300 with TSAT below 25% is one specified profile',[
 ('No, only ferritin below 15 can ever qualify','That would miss clinically important iron restriction.'),('Yes, therefore an unlimited IV dose is mandatory','Route and dose are individualized.'),('No, because ferritin and TSAT cannot be used together','Their combined interpretation is central.')],
 'Available iron can be low despite measurable stores', '**Nondialysis/PD thresholds differ from the HD thresholds.**', ['Another profile is ferritin below 100 with TSAT below 40%.','Oral or IV iron depends on efficacy, tolerance, preference and clinical need.'], '**Monitor rather than treating indefinitely.**', ['Assess Hb and iron response.','Consider blood loss and other causes if response is poor.'], [['Ferritin 180','Intermediate storage range'],['TSAT 18%','Low availability'],['Route','Individualized']], [AN], 'clinical_scenario')
q('What hemoglobin principle applies to adults with CKD receiving an ESA under KDIGO 2026?', 'Target below 11.5 g/dL rather than normalization to a high healthy-adult value',[
 ('Normalize every patient to at least 14 g/dL','Higher targets increase adverse-event concerns.'),('No monitoring is needed after initiation','Response and safety require review.'),('The same fixed starting threshold applies to every nondialysis patient regardless of symptoms','Initiation is individualized in that setting.')],
 'Treat anemia without pursuing harmful normalization', '**ESA decisions balance symptoms, transfusion avoidance and cardiovascular/thrombotic risk.**', ['Correct contributing causes first.','Use a suitable dose with follow-up.'], '**Reassess the risk-benefit balance.**', ['Stroke, cancer context and other factors can alter decisions.','Do not escalate indefinitely in hyporesponsiveness without investigation.'], [['Goal','Below 11.5 g/dL on ESA'],['Benefit','Symptoms/transfusion reduction'],['Risk','Thrombotic/cardiovascular events']], [AN])
q('ESA requirements rise markedly with little Hb improvement. What is the best next principle?', 'Investigate hyporesponsiveness, including iron restriction, inflammation, blood loss and other causes, instead of unbounded dose escalation',[
 ('Increase the dose indefinitely without review','This may add risk without correcting the cause.'),('A low TSAT is irrelevant because an ESA is being used','Iron availability remains essential.'),('Every case proves a new kidney tumor','The differential is broader.')],
 'A treatment failure can reveal an untreated mechanism', '**Inflammation and iron-restricted erythropoiesis are common contributors.**', ['Assess dialysis-related losses and adequacy when relevant.','Other hematological and nutritional causes may need evaluation.'], '**Use a structured plan.**', ['Reassess the desired Hb outcome and risks.','Coordinate nephrology and hematology when findings are atypical.'], [['Iron','Check availability'],['Inflammation/loss','Find contributors'],['Dose','Avoid reflex escalation']], [AN])
q('Why should avoidable red-cell transfusion be considered carefully in a potential kidney-transplant candidate?', 'Alloimmunization can complicate future donor matching, although urgent clinical needs may still justify transfusion',[
 ('Transfusion is forbidden even in life-threatening hemorrhage','Immediate clinical benefit can outweigh future risks.'),('Transfusion never affects transplantation','Sensitization is important.'),('An ESA is an immediate substitute during hemorrhagic shock','Its effect is delayed.')],
 'Current urgency and future access both matter', '**Transfusion can expose the patient to alloantigens.**', ['Other transfusion harms also require consideration.','Severe symptomatic or unstable anemia needs timely treatment.'], '**Avoid a rigid Hb-only rule.**', ['Use symptoms, hemodynamics and the broader situation.','Optimize correctable chronic anemia causes.'], [['Transplant candidate','Sensitization concern'],['Urgent instability','May require transfusion'],['Chronic care','Reduce avoidable exposure']], [AN])
q('How should CKD-mineral and bone disorder treatment decisions generally be made?', 'Use serial calcium, phosphate and PTH assessments together with the clinical context',[
 ('Treat a single PTH value without calcium or phosphate','The abnormalities are interrelated.'),('Bone disease is impossible before dialysis','CKD-MBD begins earlier.'),('A normal calcium excludes every CKD-MBD process','PTH and phosphate regulation can already be abnormal.')],
 'A connected endocrine system needs a connected assessment', '**Trends are more informative than isolated results.**', ['Assay variation and CKD stage affect interpretation.','Bone, vascular and biochemical consequences overlap.'], '**Avoid treating one laboratory value into another abnormality.**', ['Therapies can alter calcium and phosphate.','Reassess after changes.'], [['Calcium','Treatment safety'],['Phosphate','Retention/intake context'],['PTH','Trend and turnover context']], [MB])
q('PTH rises gradually in nondialysis CKD. What is the appropriate first principle?', 'Evaluate modifiable contributors such as phosphate burden, hypocalcemia and vitamin D deficiency rather than applying a universal normal-PTH target',[
 ('Every elevation requires immediate calcimimetic treatment','The nondialysis pathway differs.'),('The optimal nondialysis PTH is precisely established for every stage','It is not.'),('Ignore progressive marked elevations indefinitely','They warrant evaluation and management.')],
 'Some PTH adaptation occurs with declining kidney function', '**KDIGO emphasizes persistent or progressive change and modifiable factors.**', ['Dietary phosphate and vitamin D status can matter.','Interpret calcium and phosphate concurrently.'], '**Choose treatment proportional to the abnormality.**', ['Severe progressive hyperparathyroidism may require specialist therapy.','Avoid over-suppression and hypercalcemia.'], [['Initial step','Find modifiable factors'],['PTH target','No universal nondialysis number'],['Persistent progression','Specialist review']], [MB])
q('Should calcitriol or active vitamin D analogues be routinely given to every adult with nondialysis CKD G3–G5?', 'No; routine use is not recommended, with selected severe progressive hyperparathyroidism considered separately',[
 ('Yes, regardless of calcium or PTH','This can cause harm.'),('No vitamin D-related deficiency should ever be treated','Nutritional deficiency is a different question.'),('Active vitamin D cannot raise calcium','Hypercalcemia is a relevant adverse effect.')],
 'Nutritional deficiency and active-hormone treatment differ', '**KDIGO restricts routine active vitamin D use in nondialysis disease.**', ['Review calcium, phosphate and PTH trends.','Selected advanced progressive disease has a different balance.'], '**Avoid a stage-only prescription.**', ['Correct modifiable contributors.','Monitor biochemical consequences of treatment.'], [['Nutritional vitamin D','Deficiency assessment'],['Active vitamin D','Not routine for every CKD adult'],['Risk','Calcium/phosphate changes']], [MB])
q('Why may a calcium-free phosphate binder be favored in a CKD patient with recurrent hypercalcemia or substantial calcification concern?', 'It reduces phosphate binding without adding the same calcium load',[
 ('Calcium-containing binders never affect calcium balance','They can add a substantial load.'),('All phosphate binders are identical in risks and effects','They differ.'),('A binder removes the need to consider dietary phosphate sources','Dietary management remains relevant.')],
 'Phosphate control has treatment-specific tradeoffs', '**KDIGO advises restricting calcium-based binder exposure in appropriate adults.**', ['Decisions consider calcium, phosphate, PTH and vascular context.','Treat persistently elevated phosphate rather than an isolated normal value.'], '**Individualize the binder plan.**', ['Pill burden, tolerance and cost matter.','Reassess after therapy changes.'], [['Calcium binder','Adds calcium'],['Calcium-free binder','Avoids that load'],['Choice','Biochemistry and clinical context']], [MB])
q('What PTH range does KDIGO generally suggest in CKD G5D?', 'Approximately two to nine times the assay upper limit, interpreted with trends',[
 ('An exact normal-population value in every dialysis patient','Aggressive normalization can over-suppress turnover.'),('Any value is acceptable indefinitely','Marked changes require assessment.'),('A single universal absolute number independent of assay','The recommendation is assay-relative.')],
 'Dialysis targets differ from a normal laboratory range', '**The broad interval reflects uncertainty and the danger of over-suppression.**', ['Marked movement within or outside the range can prompt treatment review.','Calcium and phosphate affect drug choice.'], '**Monitor for low-turnover disease as well as excess PTH.**', ['Calcimimetics and vitamin D strategies have different tradeoffs.','Avoid automatic dose escalation from one value.'], [['G5D range','About 2–9 times ULN'],['Assay','Reference matters'],['Trend','Guides review']], [MB])
q('Persistent metabolic acidosis develops in CKD. What is the appropriate treatment principle?', 'Evaluate and consider dietary/pharmacological treatment for clinically important acidosis while monitoring BP, potassium and volume',[
 ('Every slightly low bicarbonate requires unlimited sodium bicarbonate','Treatment burden and evidence need context.'),('Acidosis is never clinically relevant','It can affect muscle, bone and other outcomes.'),('Alkali therapy has no sodium or volume consequences','These can matter.')],
 'Treat a physiological problem without creating another', '**KDIGO 2024 gives bicarbonate below 18 mmol/L as an example of acidosis with potential clinical implications.**', ['The optimal intervention threshold is not a simple universal rule for every patient.','Confirm the acid-base disorder and other causes.'], '**Follow response and safety.**', ['Avoid overcorrection.','Review diet, fluid status and potassium.'], [['Assessment','Confirm persistent acidosis'],['Treatment','Context-dependent'],['Safety','BP, potassium and volume']], [CK])
q('Should dialysis be initiated solely because eGFR crosses one fixed value in a stable CKD patient?', 'No; use symptoms, complications, preferences, trajectory and the overall clinical assessment',[
 ('Yes, every patient must start at exactly 15','That is not a universal initiation rule.'),('Never start until all urine output stops','Dangerous complications can occur with residual urine.'),('A low eGFR never requires preparation','Planning should occur before urgent need.')],
 'Preparation and initiation are different decisions', '**Uremic symptoms, refractory metabolic or volume problems and nutritional decline can guide initiation.**', ['Some patients remain stable at very low eGFR.','Others need treatment earlier because of complications.'], '**Use shared modality planning.**', ['Consider transplantation, dialysis options and conservative care where appropriate.','Avoid an unplanned emergency start when possible.'], [['Preparation','Proactive'],['Initiation','Clinical indications'],['Preferences','Central to choice']], [CK])
q('How can a two-year kidney-failure risk above about 40% assist CKD care under KDIGO 2024?', 'Guide modality education and preparation for KRT, including access or transplant referral, alongside other factors',[
 ('It mandates dialysis the same day','A planning threshold is not an immediate treatment indication.'),('It predicts the exact month of failure','Risk is probabilistic.'),('It replaces assessment of rapid decline or symptoms','Clinical factors remain important.')],
 'Risk can make preparation timely', '**A high near-term risk supports earlier practical planning.**', ['Vascular access and transplant work-ups take time.','Use the model only in an appropriate validated population.'], '**Explain options before crisis.**', ['Discuss home therapies and transplantation when suitable.','Update the plan as health and preferences change.'], [['High two-year risk','Prepare'],['Access/transplant','Lead time needed'],['Actual start','Separate indication assessment']], [CK])
q('What is comprehensive conservative kidney management?', 'Active symptom-focused and supportive care without dialysis, selected through informed shared decision-making',[
 ('Abandonment of all medical treatment','It includes ongoing active care.'),('A decision based only on age without discussing preferences','Frailty, comorbidity, goals and likely benefit matter.'),('A prohibition on revisiting the plan','Choices can be reassessed.')],
 'A nondialysis pathway can still be comprehensive care', '**Manage symptoms, fluid, anemia and other burdens in line with goals.**', ['Prognosis and treatment burden should be discussed honestly.','Palliative support can be integrated.'], '**Support patient and caregivers.**', ['Document preferences and emergency plans.','Revisit decisions as circumstances change.'], [['Care','Active supportive management'],['Decision','Informed and shared'],['Follow-up','Ongoing']], [CK])
q('A patient with advanced CKD has mucosal bleeding despite a normal platelet count. Which mechanism can contribute?', 'Uremia-associated platelet dysfunction',[
 ('A normal platelet count proves normal hemostasis','Platelet function and count differ.'),('All bleeding is automatically uremic','Other drugs and hematological causes must be assessed.'),('A normal INR excludes every bleeding disorder','INR does not assess all platelet function.')],
 'Hemostasis is not summarized by one count', '**Uremia can impair platelet adhesion and aggregation.**', ['Anemia and antiplatelet medicines can add risk.','Bleeding requires assessment of the actual source and severity.'], '**Treat the clinical problem.**', ['Dialysis optimization and selected urgent measures may be used in suitable cases.','Do not ascribe unexplained major bleeding to CKD without investigation.'], [['Platelet count','May be normal'],['Function','Can be impaired'],['Assessment','Other causes and severity']], [CK,AN], 'clinical_scenario')
q('Which intervention makes CKD medication education most useful?', 'A written individualized plan covering indications, monitoring, acute-illness actions and restarting after temporary holds',[
 ('Tell every patient to stop all medicines permanently during any minor illness','This is overly broad and can cause harm.'),('Use a temporary hold with no restart instructions','Beneficial therapy can be lost indefinitely.'),('Assume a long medication list needs no reconciliation','Complex regimens increase error risk.')],
 'A safe plan includes both interruption and resumption', '**CKD care often involves medicines with different acute and long-term effects.**', ['Teach warning symptoms and when to seek assessment.','Use clear language and check understanding.'], '**Reconcile after admissions and treatment changes.**', ['Coordinate primary, specialty and pharmacy care.','Adapt the plan to health literacy and support needs.'], [['Indication','Why the drug matters'],['Monitoring','What and when'],['Acute illness','Specific hold/restart instructions']], [CK])

if __name__=='__main__':finalize('Nephrology',2,'Chronic Kidney Disease','neph-ckd',rows,44)
